        if attack_targets:
            # deterministic min over targets
            # slight bias to reduce swapping by sorting by coords once
            # (sorted list creation is deterministic and bounded)
            if len(attack_targets) > 1:
                # avoid sorting every move; keep it minimal by using one-time local copy
                pass
        # Compute min dist without sorting: deterministic iteration
        mind = 10**18
        for t in attack_targets:
            d = dist((nx, ny), t)
            if d < mind:
                mind = d
        # Convert squared-distance to a score; smaller is better
        if mind < 10**18:
