            best_score = cell_score
            best = (dx, dy)
        elif cell_score == best_score and best is not None:
            # deterministic tie-break: smaller (dx,dy) lexicographically
            if (dx, dy) < best:
                best = (dx, dy)

    if best is None:
        return [0, 0]
    return [best[0], best[1]]

